import json
async def main(args):
    """update_wiki 之后拍 after 快照，调 diff_snapshots 子工作流 diff。
    after 快照必须【本节点执行时】拍（拍早了 diff 不到 update_wiki 的变更）——
    所以 code 节点内自己 walk 一遍（与 dir_snapshot 同逻辑），再以子工作流出结构化结果。"""
    import os
    p = args.params
    now = {}
    for root, dirs, files in os.walk(".agent/wiki"):
        dirs[:] = [d for d in dirs if d not in (".git", "__pycache__")]
        for f in files:
            fp = os.path.join(root, f).replace("\\", "/")
            try: now[fp] = os.path.getmtime(fp)
            except OSError: pass
    try:
        from workflow import _find_local_workflow, execute
        from real_tools import REAL_TOOLS
        canvas = _find_local_workflow(type("C", (), {"workspace": __import__("pathlib").Path(".")})(), "diff_snapshots")
        if canvas is not None:
            ret = execute(canvas, {"before": p.get("before"), "after": json.dumps(now)},
                          tools=REAL_TOOLS, llm=None, return_exit_dict=True)
            if isinstance(ret, dict) and "files" in ret:
                return {"files": ret["files"], "count": ret.get("count", 0)}
    except Exception:
        pass   # 子工作流不可用 → 走本地兜底，不炸主链路
    # 本地兜底 diff（与 diff_snapshots 同语义）
    def _load(s):
        try:
            d = json.loads(s or "{}"); return d if isinstance(d, dict) else {}
        except Exception: return {}
    before = _load(p.get("before"))
    changed = [fp for fp, mt in now.items() if fp not in before or abs(before.get(fp, 0) - mt) > 1e-6]
    changed += [fp for fp in before if fp not in now]
    return {"files": ",".join(changed), "count": len(changed)}

node.result:
你是 repo-wiki 维护判官。依据user message和assistant response判断本轮对话是否值得记录进项目知识库（.agent/wiki/）。
值得记录：实现了新功能、修复了 bug、做出架构/设计决策、摸清了某模块的工作原理、解决了值得备忘的问题。
不值得记录：纯闲聊、简单问答、查询信息、未产生可复用知识。
只输出一个 JSON 对象，不要 markdown：
{"needs_maintenance": true, "summary": "本轮做了什么、影响哪些模块、关键结论"}
needs_maintenance=false 时 summary 给空串。summary 要聚焦改动，简洁（交由后续子 Agent 据此 wiki_tree/wiki_read 后 wiki_write）。

